{"issue": true, "summary": "The `retriesConsumed` variable is incremented after a retry attempt fails and before the next attempt begins, but it's not reset when an attempt succeeds. This causes the retry count to be incorrectly tracked across multiple successful attempts in a row, potentially leading to early termination of retries when they should continue.", "edits": [{"path": "index.js", "old": "		try {
			options.signal?.throwIfAborted();

			const result = await input(attemptNumber);

			options.signal?.throwIfAborted();

			return result;
		} catch (error) {
			if (await onAttemptFailure({
				error,
				attemptNumber,
				retriesConsumed,
				startTime,
				options,
			})) {
				retriesConsumed++;
			}
		}", "new": "		try {
			options.signal?.throwIfAborted();

			const result = await input(attemptNumber);

			options.signal?.throwIfAborted();

			return result;
		} catch (error) {
			if (await onAttemptFailure({
				error,
				attemptNumber,
				retriesConsumed,
				startTime,
				options,
			})) {
				retriesConsumed++;
			} else {
				retriesConsumed = 0;
			}
		}"}]}
